#include <bits/stdc++.h>
using namespace std;
using ll=long long;
struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}};
struct BIT{int n;vector<int>t;BIT(int n=0):n(n),t(n+1){}void add(int x,int v){for(++x;x<=n;x+=x&-x)t[x]+=v;}int sum(int x){int r=0;for(;x>0;x-=x&-x)r+=t[x];return r;}int kth(int k){int p=0;for(int step=1<<20;step;step>>=1)if(p+step<=n&&t[p+step]<k){p+=step;k-=t[p];}return p;}};
ll power(ll a,ll b,ll mod=1000000007){ll r=1;for(;b;b>>=1,a=a*a%mod)if(b&1)r=r*a%mod;return r;}
int main(){int n,m;cin>>n>>m;vector<int>atk,def,c(m);for(int i=0;i<n;i++){string s;int v;cin>>s>>v;(s=="ATK"?atk:def).push_back(v);}for(auto&v:c)cin>>v;sort(atk.begin(),atk.end());sort(def.begin(),def.end());sort(c.begin(),c.end());int ans=0;for(int k=1;k<=min((int)atk.size(),m);k++){int sum=0;bool good=true;for(int j=0;j<k;j++){int v=c[m-k+j];if(v<atk[j])good=false;sum+=v-atk[j];}if(good)ans=max(ans,sum);}multiset<int>left(c.begin(),c.end());bool good=true;int sum=0;for(int v:def){auto it=left.upper_bound(v);if(it==left.end()){good=false;break;}left.erase(it);}if(good)for(int v:atk){auto it=left.lower_bound(v);if(it==left.end()){good=false;break;}sum+=*it-v;left.erase(it);}if(good){for(int v:left)sum+=v;ans=max(ans,sum);}cout<<ans<<'\n';}
